    public static int countCells(int n, int m, char[][] grid) {
        // 四个方向：上、下、左、右
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        int ans = 0;

        // 枚举每一个单元格
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // 墙不能翻转，直接跳过
                if (grid[i][j] == '#') {
                    continue;
                }

                int deg = 0; // 当前非墙单元格的非墙邻居数量

                // 统计四个方向中非墙邻居的个数
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];

                    if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] != '#') {
                        deg++;
                    }
                }

                // 邻居数为偶数，则翻转后整体奇偶性不变
                if (deg % 2 == 0) {
                    ans++;
                }
            }
        }

        return ans;
    }

